  // (l'élément de remplissage d'une roche grenue, `espacement`, n'est jamais visé : il se règle par `remplit`)
  const est = (o, k) => !o.espacement && (o.min === k || o.cle === k || o.type === k);
  // retouche d'une liste de réglages : élément repéré par son minéral, sa clé ou son type ; null = retiré
  const regle = (liste, k, x) => liste.flatMap((o) => (est(o, k) ? (x === null ? [] : [{ ...o, ...x }]) : [o]));
